      "summary": "到那日，在耶路撒冷存留的必称为圣。主必以审判的灵与焚烧的灵洗净锡安女子的污秽，又在锡安全家之上日间造云柱、夜间造火柱作为荣耀遮蔽，像昔日出埃及时那样保护他的百姓。",
      "theme": "审判之后神必洁净余民，以同在的荣耀遮蔽保护他们。",
