      "summary": "论大马士革的默示：看哪，大马士革已被废弃，不再为城，必变作乱堆。以法莲不再有保障。到那日，雅各的荣耀必衰落，他必如同收割的人收聚禾捆。因你忘记救你的神，不记念你能力的磐石，所以你栽上佳美的枝子，使它发旺的日子，就是灾难的日子。",
