      "summary": "唉！古实河外翅膀刷刷响声之地，差遣使者在水面上坐蒲草船过海。耶和华说：\"我要安静，在我的居所观看，如同日光中的炽热，又如收割时候露水蒸腾的云。\"到那时，这高大光滑的民必当作礼物献给万军之耶和华。",
