      "summary": "旷野和干旱之地必然欢喜，沙漠也必快乐，又像玫瑰开花。那时瞎子的眼必睁开，聋子的耳必开通。那时瘸子必跳跃像鹿，哑巴的舌头必能歌唱。在旷野必有水发出，在沙漠必有河涌流。必有一条大道，称为圣路，污秽人不得经过，必专为赎民行走。耶和华救赎的民必归回，歌唱来到锡安，永乐必归到他们的头上。",
