      "summary": "那时希西家病得要死。以赛亚说：\"耶和华如此说：你当留遗命与你的家，因为你必死不能活了。\"希西家就转脸朝墙，祷告耶和华。希西家就痛哭了。耶和华的话临到以赛亚说：\"我听见了你的祷告，看见了你的眼泪，我必加增你十五年的寿数。这是给你的兆头：日影在日晷上后退十度。\"",
      "theme": "神听见眼泪与祷告，有权延长寿命、改变自然规律。",
