          "content": "这是全章最核心、也被新约直接应验在耶稣身上的段落（太12:17-21）。神亲自开口介绍这位仆人：身份：我所扶持、所拣选、心里所喜悦的，已将我的灵赐给他——三位一体味道很浓，父介绍子、灵降在子上；使命：必将公理传给外邦……作众民的中保（原文约）、作外邦人的光，开瞎子的眼、领被囚的出牢狱（7节）；行事风格（这段最打动人）：他不喧嚷，不扬声，也不使街上听见他的声音。压伤的芦苇，他不折断；将残的灯火，他不吹灭。他凭真实将公理传开，不灰心也不丧胆，直到在地上设立公理。（42:2-4）这里有个重要对照：41章神称被拣选的以色列是虫雅各——弱小却被抓住不松手；42章这位真仆人则把软弱者不折断不吹灭的怜悯活出来。旧约层面仆人可指以色列民族（41:8），但这首诗歌用单数、有个体性格与使命，明显超越民族范畴，新约马太明确把它套在耶稣身上——耶稣受洗时圣灵降下（对应42:1已将我的灵赐给他），事奉中拒绝政治暴力、医治破碎者、对外邦人也施怜悯，完全对得上不喧嚷、压伤芦苇不折断的画像。8-9节收尾：神的荣耀不归给假神，先前的事（审判、被掳）已成就，现在要说新事——指向后面归回与终极救赎。"
