      "summary": "以赛亚书第44章紧接43章的法庭场景，进入真神与假神的正面交锋。前半（1-8节）以浇灌活水的应许宣告神的真实——他将灵浇灌后裔如水浇灌旱地；中段（9-20节）是旧约最辛辣的偶像讽刺——匠人砍一棵树，一半烤饼吃饱，一半雕成神像跪拜，极其荒谬；后半（21-28节）转向赦免与归回，宣告我涂抹了你的过犯如厚云消散，并首次点名古列为重建圣殿的牧人。整章在神的灵如水浇灌与偶像不过是木头的对照中，揭示敬拜的本质：要么敬拜造物主，要么被受造物蒙蔽。",
