      "summary": "以赛亚书第46章用一幅极具画面感的对比，为巴比伦的偶像崇拜画上句号：当巴比伦沦陷、百姓逃难时，金银打造的彼勒和尼波被驮在牲畜上，成了使牲畜疲乏的重担——它们不但不能救人，自己反被掳去（1-2节）。与此形成尖锐对照的是耶和华：你们自从生下就蒙我保抱，自从出胎便蒙我怀搋，直到你们年老我仍这样，直到你们发白我仍怀搋（3-4节）——偶像要人抬着走，真神却从出生抱到老死。全章在后半（8-13节）转入对顽梗者的呼吁：追念上古之事，认识我的筹算必立定，并以我的救恩必不迟延作结。",
