      "summary": "以赛亚书第47章是一首针对巴比伦的讽刺挽歌。前一章刚宣告彼勒尼波弯腰、偶像成了重担，本章直接对着巴比伦本人喊话：从宝座下来，坐在尘埃，露腿涉河，磨面脱帕——这是战俘奴隶的待遇，与昔日列国主母的荣耀形成残酷对比。全章揭示巴比伦败亡的两个根源：①对被掳之民毫不怜悯（6节），把极重的轭加在老年人身上；②狂妄自恃，心中说惟有我除我以外再没有别的（8、10节），且倚靠邪术符咒（9、12节）。最终的结局是：她所倚靠的智慧人、观天象的、看星宿的，都像碎稭被火焚烧，无人能救她。",
