      "summary": "以赛亚书第48章是第二以赛亚前半段（40-48章）的总结章，也是对以色列最严厉的责备。神指出百姓的致命问题：他们指着耶和华的名起誓提说以色列的神，却不凭诚实不凭公义（1节）——宗教外壳下的虚伪。神从古时预言将来事，不是因为他们配，而是免得他们说这些事是偶像所行的（5节）。全章在两条线推进：①神对顽梗百姓的忍耐与熬炼（1-11节）——我为我的名暂且忍怒；②新出埃及的宣告（12-22节）——从巴比伦出来，神必如古时使水从磐石流出。全章以一句沉重的话收尾：恶人必不得平安（22节）。",
