      "summary": "以赛亚书第49章是四首仆人之歌的第二首（另三首在42、50、52-53章），也是救恩从以色列扩展到普世的转折点。仆人自述从母腹被选召，口如快刀、如磨亮的箭（1-3节），却在事奉中经历劳碌徒然的挫折（4节）；但神宣告他的使命远超复兴以色列——我还要使你作外邦人的光叫你施行我的救恩直到地极（6节）。后半（14-26节）是锡安的复兴之歌：锡安以为自己被遗忘，神却以母性的比喻回应妇人焉能忘记她吃奶的婴孩（15节），并宣告列王必作你的养父王后必作你的乳母（23节）。整章在仆人的普世使命与锡安的母性安慰中，展现神救恩的两个维度：向外直到地极，向内怀抱每一个以为被遗弃的儿女。",
