      "summary": "以赛亚书第52章是第二以赛亚中段的枢纽：前半（1-12节）以三重兴起呼吁锡安从尘埃中起来、抖下锁链、离开巴比伦，因为你的神作王了；后半（13-15节）开启第四首仆人之歌的序曲——我的仆人必被高举上升且成为至高，但许多人因他惊奇，因为他的面貌比别人憔悴他的形容比世人枯槁。全章在锡安的荣耀归回与仆人的受苦被高之间形成巨大张力：锡安得释放的代价是仆人被压伤。7节那报佳音传平安传救恩的这人的脚登山何等佳美被新约罗马书10:15引用，成为历代传福音者的经文。",
