      "summary": "以赛亚书第53章是第四首仆人之歌的核心，也是整本旧约最精确的基督十字架预言。紧接52:13-15的序曲（仆人必被高举却面貌憔悴），本章以五个段落展开受苦仆人的画像：①谁能信（1-3节）——仆人如嫩芽出于干地，无佳形美容，被人藐视；②代罪受刑（4-6节）——他担当我们的忧患，耶和华将众人的罪孽归在他身上；③无声受死（7-9节）——如羊羔被牵宰杀，与财主同葬；④耶和华定意压伤（10-12节）——以他为赎罪祭，他却为罪犯代求。全章在新约被引用约40次，腓利向埃塞俄比亚太监传讲的正是这章（徒8:32-33），是旧约对基督十字架最完整、最精确的预言。",
