      "summary": "以赛亚书第54章紧接53章仆人代罪受死，是救赎果效的第一幅画面：因仆人的赎罪，锡安要如不怀孕的忽然多生儿女。全章以三段展开：①歌唱扩张（1-3节）——不怀孕的要歌唱，扩张帐幕，因后裔必得多国为业；②永远慈爱（4-10节）——不要惧怕，造你的是你的丈夫，大山可以挪开但我的慈爱必不离开你；③荣耀重建（11-17节）——以蓝宝石红宝石重建，凡攻击你的器械必不利用。整章是53章代赎之后的\"因此\"——因为仆人担当了罪，锡安的羞辱被永远除去，神以丈夫的身份召回被弃的妻子，以永远的慈爱保护她。",
