      "summary": "以赛亚书第56章是全书最后一段（56-66章）的开篇，也是救恩范围从以色列扩展到普世的关键宣告。前半（1-8节）宣告神接纳两类被排除的人：太监（申23:1规定不能入会幕）和外邦人——只要他们守安息日、持守神的约，神必赐他们永远的名、领他们到圣山，因我的殿必称为万民祷告的殿。后半（9-12节）画风骤变，转向对以色列堕落领袖的审判：看守的人是瞎眼的、哑巴狗不能叫唤、贪食不知饱足、各人偏行己路求自己的利益。整章在接纳外邦与审判领袖的对照中，揭示一个悖论：外邦人因信被纳入恩典，以色列的领袖却因贪欲被弃绝。",
