      "summary": "以赛亚书第65章是全书末段（56-66章）中审判与应许交织最密集的一章。1-7节神宣告他向外邦伸出双手（素来没有访问我的现在求问我），却整天招呼悖逆的百姓而他们随己意行不善之道。8-16节以葡萄中寻得新酒的比喻宣告：不全然毁灭，必有余民存留，但悖逆者必饥饿蒙羞。17-25节是全章的荣耀高峰：看哪我造新天新地，从前的事不再被记念——其中不再有哭泣、不再有婴孩夭亡、建造的自己居住、栽种的自己享用、豺狼与羊羔同食。这段在新约彼后3:13与启21:1被直接引用，指向最终的荣耀更新。全章在\"我整天伸手招呼\"（2节）与\"我造新天新地\"（17节）之间，揭示神的心意是拯救而非毁灭。",
