          "range": "1-7节",
          "heading": "我整天伸手——外邦遇见，以色列悖逆",
          "content": "1节素来没有访问我的现在求问我没有寻找我的我叫他们遇见没有称为我名下的我对他们说我在这里——外邦人意外地遇见了神。这节被新约罗10:20引用，说明救恩转向外邦。2节我整天伸手招呼那悖逆的百姓他们随自己的意念行不善之道——与外邦形成对比，以色列反而不理会神整天的伸手。3-5节列举悖逆的宗教行为：在园中献祭、在坟墓间住宿、吃猪肉、器皿中有可憎之物——这些是混合宗教的具体表现。更可悲的是5节对人说你站开吧不要挨近我因为我比你圣洁——自以为圣却行可憎之事。6节看哪这都写在我面前我必不静默必施行报应——罪已被记录审判必临到。"
