          "range": "17-25节",
          "heading": "新天新地——豺狼与羊羔同食",
          "content": "17节看哪我造新天新地从前的事不再被记念也不再追想——这是以赛亚书最辉煌的应许。被新约彼后3:13与启21:1直接引用。18节你们当因我所造的永远欢喜快乐——新造带来永恒的喜乐。19节其中必不再听见哭泣的声音和哀号的声音——一切悲哀终止。20节其中必没有数日夭亡的婴孩也没有寿数不满的老者——死亡被征服。21-22节他们要建造房屋自己居住栽种葡萄园吃其中的果子——劳有所得，不再被掠夺。23节他们必不徒然劳碌所生产也不遭灾害——劳动的果子有保障。24节他们尚未求告我就应允正说话的时候我就垂听——祷告不必等候，神即时回应。25节豺狼必与羊羔同食狮子必吃草与牛一样尘土必作蛇的食物——受造界的和谐恢复，与11:6-9呼应。在我圣山的遍处这一切都不伤人不害物——全地恢复伊甸的平安。"
