      "summary": "以赛亚书第66章是全书的终章，在三个段落中收束整卷的神学主题。①虚心痛悔者 vs 假冒为善者（1-6节）——天是我的座位地是我的脚凳，神不看殿宇而看虚心痛悔因话战兢的人；假冒为善者的献祭如同杀人。②锡安的生产与安慰（7-14节）——锡安未曾劬劳就生产，国岂能一日而生？神以母亲的比喻安慰：母亲怎样安慰儿子我就照样安慰你们。③末后的审判与招聚（15-24节）——耶和华在火中降临以烈怒施行报应，却同时招聚万民万族来见他的荣耀，差遣逃脱者到列国传扬。全章以24节\"虫是不死的火是不灭的\"收尾——这是耶稣在可9:48引用描述最终审判的经文。恩典与审判在以赛亚书中至终并存：新天新地长存，悖逆者有永火。",
